def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([-3, -3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([2, 2, 2, 2]),
             fmt([-10**9, 10**9, -10**9, 10**9])]
    for n in (2, 3, 4, 6, 8, 10, 12, 15):
        for _ in range(3):
            tests.append(fmt([rng.randint(-6, 6) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(3000)]))
    N = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)]))
    return tests
